def component(name, family, anatomy, dimensions, padding, label, behavior, variants=None, overrides=None):
    return {"name":name,"family":family,"variants":variants or ["default"],"anatomy":anatomy,"dimensions":dimensions,"padding":padding,"states":COMMON_STATES | (overrides or {}),"accessibilityLabel":label,"behavior":behavior}

