rows=[]
def pair(theme, fg, bg, threshold, purpose):
    colors=THEMES[theme]
    ratio=contrast(colors[fg],colors[bg])
    rows.append({"theme":theme,"foregroundToken":fg,"backgroundToken":bg,"foreground":colors[fg],"background":colors[bg],"ratio":round(ratio,4),"threshold":threshold,"result":"PASS" if ratio+1e-10>=threshold else "FAIL","purpose":purpose,"webaim":"https://webaim.org/resources/contrastchecker/?fcolor="+colors[fg][1:]+"&bcolor="+colors[bg][1:]})

for theme in THEMES:
    for surface in ["background","surface","surfaceHover","surfacePressed"]:
        for fg in ["text","muted","primary","secondary","accent","success","warning","error","info"]:
            pair(theme,fg,surface,4.5,"Normal text / label on " + surface)
        for fg in ["border","primary","secondary","error","focus"]:
            pair(theme,fg,surface,3,"Interactive boundary, meaningful icon, or focus ring against " + surface)
    for fill in ["primary","primaryHover","primaryPressed","secondary","accent","success","warning","error","info"]:
        pair(theme,"onBrand",fill,4.5,"Filled control label / checkbox tick / toggle thumb")
        for surface in ["surface","background"]:
            pair(theme,fill,surface,3,"Filled interactive shape against adjacent " + surface)
    for semantic in ["success","warning","error","info"]:
        pair(theme,semantic,semantic+"Surface",4.5,"Semantic badge message and status icon")
        pair(theme,"text",semantic+"Surface",4.5,"Semantic panel primary copy")
        pair(theme,"focus",semantic+"Surface",3,"Focus around action inside semantic panel")
    pair(theme,"muted","disabledSurface",4.5,"Disabled control text remains readable")
    pair(theme,"border","disabledSurface",3,"Disabled control boundary")
    pair(theme,"text","disabledSurface",4.5,"Read-only value")
    pair(theme,"focus","disabledSurface",3,"Focusable explanatory read-only control")

failed=[r for r in rows if r['result']=='FAIL']
if failed:
    print(json.dumps(failed,indent=2))
    raise SystemExit("Adjust token or remove unsupported usage before generating approved artifacts")
