assert contrast('#777777','#FFFFFF')<4.5
assert all(t['size']>=16 and t['lineHeight']>=1.5*t['size'] for t in TYPOGRAPHY)
TOKENS['approvedPairs']=rows
(OUT/'tokens.json').write_text(json.dumps(TOKENS,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
(OUT/'components.json').write_text(json.dumps({"components":COMPONENTS,"icons":[dict(name=n,description=d,accessibleLabel=a) for n,d,a in ICONS],"variantAxes":["Theme: Light / Dark","State: Default / Hover / Pressed / Disabled / Focus","Size: Preferred56 / Minimum48","TextScale: 100 / 200","Platform: iOS / Android"],"figmaHandoff":"Create native Figma component sets and variables from these specifications; this JSON is not a Figma library."},indent=2,ensure_ascii=False)+'\n',encoding='utf-8')

